SELECT CASE WHEN status IN ('CLOSED', 'FROZEN') THEN 'priority' ELSE 'other' END status_group, ROUND(AVG(balance), 2) avg_balance, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(account_type))) account_type_values, COUNT(DISTINCT balance) unique_statuss FROM accounts WHERE account_type != 'CREDIT' AND (balance BETWEEN 28000 AND 55000 OR opened_date <= '2023-05-01') GROUP BY 1 ORDER BY avg_balance DESC
